nextflow_process {

    name "Test Process TIDDIT_SV"
    script "../main.nf"
    process "TIDDIT_SV"

    tag "modules"
    tag "modules_nfcore"
    tag "tiddit"
    tag "tiddit/sv"
    tag "bwa/index"

    test("sarscov2 - bam - bwa") {

        setup {

            run("BWA_INDEX") {
                script "../../../../nf-core/bwa/index/main.nf"
                process {
                    """
                    input[0] =  [ [id: 'test'],
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                            ]
                    input[1] = []
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [ [ id:'test' ], // meta map
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true)
                        ]
                // fasta
                input[1] = [ [id: 'test'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                        ]
                // bwa_index
                input[2] = BWA_INDEX.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.ploidy[0][1]).readLines().contains("Chromosome	Ploidy	Ploidy_rounded	Mean_coverage") },
                { assert snapshot(path(process.out.vcf[0][1]).vcf.header.getColumnCount(), process.out.findAll { key, val -> key.startsWith("versions") }).match() }
            )
        }

    }

